export async function onCreateLead(ctx) {
  const data = ctx.input;
  // гарантируем наличие статуса, если клиент его не передал
  if (!data.status) {
    data.status = "new"; // значение по умолчанию, должно соответствовать enum
  }
  return ctx.db.lead.create(data);
}

