export async function notifyLead(ctx) {
  try {
    await ctx.integrations.mail.send({ to: ctx.owner.email, subject: 'Новая заявка', body: ctx.record });
    await ctx.integrations.tg.send({ chatId: ctx.owner.tgId, text: 'Новая заявка' });
  } catch (e) {
    // логируем ошибку и ставим статус «error» для последующего повторного уведомления
    await ctx.db.lead.update(ctx.record.id, { status: 'error' });
    ctx.logger.error('Failed to send lead notification', e);
  }
}

